public record BatchReadyPayload(UUID sessionId, UUID wandId, String dimension, long batchSequence, List<ChunkCoordinate> chunks) implements CustomPacketPayload { public BatchReadyPayload { chunks=List.copyOf(chunks); } public static final Type<BatchReadyPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(MineToMeshInfo.MOD_ID,"batch_ready")); public static final StreamCodec<FriendlyByteBuf,BatchReadyPayload> STREAM_CODEC=StreamCodec.of(SessionPayloadCodecs::ready,SessionPayloadCodecs::ready); @Override public Type<? extends CustomPacketPayload> type(){return TYPE;} }
